/* Variables
/* ---------------------------------------------------------- */

:root {

    /* Colours */
    --color-primary: #C9A6A0;
    --color-base: #1A1A1A;
    --color-border: #E5DDD5;
    --color-bg: #FAF7F2;
    --color-accent: #C4A265;
    --color-bg-subtle: #F3EDE6;

    /* Fonts */
    --font-sans-serif: 'Avenir Next', 'Futura', 'Century Gothic', sans-serif;
    --font-serif: 'Iowan Old Style', 'Palatino Linotype', 'Book Antiqua', Georgia, serif;
    --font-display: 'Cormorant Garamond', 'Iowan Old Style', Georgia, serif;
    --font-mono: Menlo, Courier, monospace;
    --font-light: 100;
    --font-normal: 400;
    --font-bold: 700;
    --font-heavy: 800;

    /* Breakpoints */
    --xlarge: 1680px;
    --large: 1280px;
    --medium: 980px;
    --small: 740px;
    --xsmall: 480px;

    /* Sizes */
    --height: 4rem;
    --margin: 2rem;
    --radius: 0.2rem;

}

[data-theme='dark'] {
    --color-primary: #D4B5AF;
    --color-base: #E8E2DC;
    --color-border: #3A3530;
    --color-bg: #171514;
    --color-accent: #D4B280;
    --color-bg-subtle: #1E1C1A;
}

