file.content:
:root {
  --header-height: clamp(4rem, 1vw + 3.5rem, 5rem);
  --site-shell-gap: clamp(1rem, 2vw, 1.8rem);
  --footer-reveal: clamp(11rem, 20vw, 15rem);
}

/* Site Wrapper
/* ---------------------------------------------------------- */

.site-wrapper {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--color-border) 35%, transparent) 1px, transparent 1px)
      50% 0 / min(88vw, 1180px) 100% no-repeat,
    var(--color-bg);
  min-height: 100vh;
  color: var(--color-base);
  font-family: var(--font-serif);
  position: relative;
}

.site-content-shell {
  position: relative;
  z-index: 2;
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
}

[data-theme='dark'] .site-wrapper {
  background: radial-gradient(circle at top, rgba(201, 166, 160, 0.05), transparent 50%),
    var(--color-bg);
}

/* Header
/* ---------------------------------------------------------- */

.site-head {
  position: sticky;
  top: 0;
  width: 100%;
  background: rgba(250, 247, 242, 0.95);
  backdrop-filter: blur(8px);
  box-shadow: none;
  border-bottom: 1px solid var(--color-border);
  z-index: 20;
}

[data-theme='dark'] .site-head {
  background: rgba(23, 21, 20, 0.95);
  box-shadow: none;
  border-bottom-color: var(--color-border);
}

.site-head-container {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 var(--site-shell-gap);
  height: var(--header-height);
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: clamp(2rem, 5vw, 6rem);
}

.site-head-logo img {
  display: block;
  width: clamp(10rem, 13vw, 13.5rem);
  max-height: calc(var(--header-height) - 1rem);
}

.site-head-nav {
  display: flex;
  justify-content: flex-end;
  gap: clamp(1.2rem, 3vw, 2.6rem);
  align-items: center;
}

.site-head-nav a {
  position: relative;
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  font-family: var(--font-sans-serif);
  font-size: 1rem;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  font-weight: 300;
  color: var(--color-base);
  opacity: 0.6;
  text-decoration: none;
  transition: opacity 0.3s ease, color 0.3s ease;
}

.site-head-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0.13em;
  bottom: 0.55rem;
  height: 1px;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 0.25s ease;
}

.site-head-nav a:hover,
.site-head-nav a[aria-current='page'] {
  opacity: 1;
  color: var(--color-accent);
  text-decoration: none;
}

.site-head-nav a:hover::after,
.site-head-nav a[aria-current='page']::after {
  transform: scaleX(1);
  transform-origin: left;
}

.site-head a:focus-visible,
.site-foot a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

/* Footer
/* ---------------------------------------------------------- */

.site-foot {
  margin-top: var(--site-shell-gap);
  padding: 3rem var(--site-shell-gap) 4rem;
  border-top: 1px solid var(--color-border);
}

[data-theme='dark'] .site-foot {
  border-top-color: var(--color-border);
  background: linear-gradient(180deg, var(--color-bg), var(--color-bg-subtle));
}

.site-foot-logo {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0.18;
}

.site-foot-logo svg {
  width: min(94vw, 820px);
  height: auto;
}

.site-foot-logo svg .st0 {
  fill: none;
  stroke: rgba(40, 37, 32, 0.5);
  stroke-width: 1.5;
  stroke-dasharray: 2800;
  stroke-dashoffset: 2800;
  animation: footer-logo-write 5.8s cubic-bezier(0.67, 0.01, 0.38, 0.98) forwards;
}

.site-foot-logo svg path:nth-of-type(2) {
  animation-delay: 0.3s;
}

.site-foot-logo svg path:nth-of-type(3) {
  animation-delay: 0.6s;
}

.site-foot-logo svg path:nth-of-type(4) {
  animation-delay: 0.9s;
}

.site-foot-logo svg path:nth-of-type(5) {
  animation-delay: 1.2s;
}

.site-foot-inner {
  max-width: 1320px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.8rem;
  position: relative;
  z-index: 2;
}

.site-foot-brand strong {
  font-family: var(--font-display);
  font-weight: 300;
  letter-spacing: 0.06em;
  font-size: 1.2rem;
}

.site-foot-bio {
  flex: 1 1 auto;
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 4rem);
  font-family: var(--font-sans-serif);
  font-size: 0.95rem;
  line-height: 1.5;
  letter-spacing: 0.035em;
  text-align: center;
  max-width: 58ch;
  white-space: normal;
  color: var(--color-base);
  opacity: 0.48;
}

.site-foot-nav {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.site-foot-nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-family: var(--font-sans-serif);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 300;
  font-size: 1rem;
  color: var(--color-base);
  opacity: 0.68;
  text-decoration: none;
  transition: opacity 0.3s ease, color 0.3s ease;
}

.site-foot-nav a:hover {
  opacity: 1;
  color: var(--color-accent);
  text-decoration: none;
}

/* Responsive
/* ---------------------------------------------------------- */

@keyframes footer-logo-write {
  to {
    stroke-dashoffset: 0;
  }
}


@media (prefers-reduced-motion: reduce) {
  .site-foot-logo svg .st0 {
    animation: none;
    stroke-dashoffset: 0;
  }
}
@media (max-width: 700px) {
  .site-head-container {
    height: auto;
    grid-template-columns: 1fr;
    gap: 0.35rem;
    padding-block: 0.65rem 0.35rem;
  }

  .site-head-logo {
    justify-self: center;
  }

  .site-head-logo img {
    width: 11rem;
  }

  .site-head-nav {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 0;
  }

  .site-head-nav a {
    justify-content: center;
    font-size: 0.9rem;
  }

  .site-foot {
    min-height: clamp(13rem, 40vw, 16rem);
    padding-bottom: 2.2rem;
  }

  .site-foot-inner {
    flex-direction: column;
    align-items: flex-start;
  }

  .site-foot-bio {
    order: 3;
    width: 100%;
    padding-inline: 0;
    text-align: left;
  }

  .site-foot-logo {
    opacity: 0.12;
  }
}

