file.content:
.legacy-page {
  width: min(100%, 1180px);
  margin: 0 auto;
  display: grid;
  gap: clamp(2rem, 4vw, 3.5rem);
  padding-bottom: clamp(3rem, 6vw, 5rem);
}

.legacy-page-hero {
  display: grid;
  gap: clamp(1.5rem, 3vw, 3rem);
  align-items: start;
}

.legacy-page-hero.has-media {
  grid-template-columns: minmax(0, 1fr) minmax(280px, 34rem);
}

.legacy-page-copy {
  display: grid;
  gap: 1rem;
}

.legacy-page-eyebrow {
  margin: 0;
  font-family: var(--font-sans-serif);
  font-size: 1rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.legacy-page h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 4.6rem);
  line-height: 0.95;
  font-weight: 400;
  letter-spacing: 0.01em;
}

.legacy-page p {
  margin: 0;
  font-size: 1.02rem;
  line-height: 1.75;
  max-width: 68ch;
}

.legacy-page-hero-media,
.legacy-page-frame {
  margin: 0;
}

.legacy-page-hero-media img,
.legacy-page-frame img {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 1.25rem;
  background: var(--color-bg-subtle);
}

.legacy-page--home {
  gap: clamp(3rem, 7vw, 6rem);
}

.legacy-page--home .legacy-page-hero {
  min-height: min(680px, calc(100vh - var(--header-height) - 7rem));
  grid-template-columns: minmax(0, 0.82fr) minmax(340px, 1.18fr);
  align-items: center;
}

.legacy-page--home .legacy-page-copy {
  gap: clamp(1rem, 2vw, 1.5rem);
  padding-right: clamp(0rem, 4vw, 4rem);
}

.legacy-page--home h1 {
  max-width: 10ch;
  font-size: clamp(4.4rem, 7.5vw, 8rem);
  line-height: 0.82;
  letter-spacing: -0.025em;
}

.legacy-page--home .legacy-page-copy > p:not(.legacy-page-eyebrow) {
  max-width: 40ch;
  color: color-mix(in srgb, var(--color-base) 68%, transparent);
  font-size: clamp(1rem, 1.4vw, 1.2rem);
}

.legacy-page--home .legacy-page-hero-media {
  align-self: stretch;
  min-height: 34rem;
}

.legacy-page--home .legacy-page-hero-media img {
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
  border-radius: 14rem 14rem 1.25rem 1.25rem;
  filter: saturate(0.88) contrast(1.02);
}

.legacy-page--home .legacy-page-links {
  margin-top: clamp(-5rem, -5vw, -2rem);
}

.legacy-page--home .legacy-page-links ul {
  display: flex;
  flex-wrap: wrap;
}

.legacy-page--home .legacy-page-links a {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  padding-inline: 1.4rem;
}

.legacy-page--home .legacy-page-gallery {
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: clamp(0.65rem, 1.2vw, 1rem);
}

.legacy-page--home .legacy-page-frame {
  grid-column: span 4;
}

.legacy-page--home .legacy-page-frame:nth-child(5n + 1),
.legacy-page--home .legacy-page-frame:nth-child(5n + 4) {
  grid-column: span 8;
}

.legacy-page--home .legacy-page-frame img {
  height: clamp(22rem, 38vw, 34rem);
  object-fit: cover;
}

.legacy-page-links ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: 0.85rem;
}

.legacy-page-links a {
  display: block;
  padding: 1rem 1.1rem;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  text-decoration: none;
  color: var(--color-base);
  font-family: var(--font-sans-serif);
  letter-spacing: 0.04em;
  transition:
    border-color 0.25s ease,
    color 0.25s ease,
    transform 0.25s ease;
}

.legacy-page-links a:hover {
  color: var(--color-accent);
  border-color: var(--color-accent);
  transform: translateY(-1px);
}

.legacy-page-gallery {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(10px, 1.25vw, 18px);
}

.legacy-page--gallery .legacy-page-gallery {
  width: min(calc(100vw - 3rem), 1440px);
  justify-self: center;
}

.legacy-page--gallery .legacy-page-frame {
  min-width: 0;
  overflow: hidden;
  background: var(--color-bg-subtle);
}

.legacy-page--gallery .legacy-page-frame.is-full-span {
  grid-column: 1 / -1;
}

.legacy-page--gallery .legacy-page-frame.is-half-span {
  grid-column: span 1;
  aspect-ratio: 2 / 3;
}

.legacy-page--gallery .legacy-page-frame.is-half-span img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.legacy-page--gallery .legacy-page-frame.is-full-span img {
  width: 100%;
  height: auto;
}

.legacy-page--gallery .legacy-page-frame img {
  border-radius: clamp(0.6rem, 1vw, 1.25rem);
}

.legacy-page-body {
  display: grid;
  gap: 1rem;
}

@media (max-width: 900px) {
  .legacy-page-hero.has-media {
    grid-template-columns: 1fr;
  }

  .legacy-page--home .legacy-page-hero {
    min-height: 0;
    grid-template-columns: 1fr;
  }

  .legacy-page--home .legacy-page-copy {
    padding-right: 0;
  }

  .legacy-page--home .legacy-page-hero-media {
    min-height: 28rem;
  }

  .legacy-page--home .legacy-page-links {
    margin-top: -1rem;
  }
}

@media (max-width: 640px) {
  .legacy-page--home h1 {
    font-size: clamp(4rem, 16vw, 5.8rem);
  }

  .legacy-page--home .legacy-page-frame,
  .legacy-page--home .legacy-page-frame:nth-child(5n + 1),
  .legacy-page--home .legacy-page-frame:nth-child(5n + 4) {
    grid-column: span 6;
  }

  .legacy-page--home .legacy-page-frame:nth-child(3n + 1) {
    grid-column: 1 / -1;
  }

  .legacy-page--home .legacy-page-frame img {
    height: 24rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .legacy-page-links a {
    transition: none;
  }
}

