body {
    margin: 0;
    background: var(--color-bg);
    color: var(--color-base);
    font-family: var(--font-serif);
}

.site-main {
    padding: clamp(2.5rem, 5vw, 5rem) 1.5rem clamp(4rem, 8vw, 7rem);
}

.site-breadcrumbs {
    display: none;
}

.post-feed {
    display: grid;
    grid-template-columns: 1.15fr 0.85fr;
    gap: 2rem;
    max-width: 112rem;
    margin: 0 auto;
}

/* Every 5th card (starting from 3rd) spans full width for variety */
.post-feed .post-card:nth-child(5n+3) {
    grid-column: 1 / -1;
}

.page-head {
    text-align: center;
    max-width: 68rem;
    margin: 0 auto 3rem;
    padding: 0;
}

.page-head-title {
    font-size: clamp(3.6rem, 4vw, 5.4rem);
    line-height: 1.1;
    font-weight: 300;
    font-family: var(--font-display);
    letter-spacing: 0.04em;
}

@media (max-width: 900px) {
    .site-main {
        padding-top: 3rem;
    }

    .post-feed {
        grid-template-columns: 1fr;
        gap: 1.8rem;
    }
}

