---
const pathname = Astro.url.pathname.replace(/\/+$/, "") || "/";
const links = [
    { label: "Discover", href: "/lookbook", section: "/lookbook" },
    { label: "Archive", href: "/daily-diary", section: "/daily-diary" },
    { label: "About", href: "/about-lovely-sunday", section: "/about-lovely-sunday" },
    { label: "Contact", href: "/contact-lovely-sunday", section: "/contact" },
];

const isCurrent = (section: string) =>
    pathname === section || pathname.startsWith(`${section}/`);
---

<header class="site-head">
    <div class="site-head-container">
        <a class="site-head-logo" href="/" aria-label="Lovely Sunday home">
            <img src="/img/lovely-sunday-logo.svg" alt="Lovely Sunday" />
        </a>

        <nav class="site-head-nav" aria-label="Primary">
            {links.map((link) => (
                <a
                    href={link.href}
                    aria-current={isCurrent(link.section) ? "page" : undefined}
                >
                    {link.label}
                </a>
            ))}
        </nav>
    </div>
</header>

---
import { readFileSync } from "node:fs";

const links = [
  { label: "Discover", href: "/lookbook" },
  { label: "Archive", href: "/daily-diary" },
  { label: "Contact", href: "/contact-lovely-sunday" },
  { label: "Instagram ↗", href: "https://www.instagram.com/lovelysunday", external: true },
];
const currentYear = new Date().getFullYear();
const footerLogoSvg = readFileSync(
  new URL("../../public/img/lovely-sunday-logo.svg", import.meta.url),
  "utf-8",
)
  .replace(/<\?xml[^?]*\?>\s*/g, "")
  .replace(/<!DOCTYPE[^>]*>\s*/g, "");
---

<footer class="site-foot">
  <div class="site-foot-logo" aria-hidden="true" set:html={footerLogoSvg} />

  <div class="site-foot-inner">
    <div class="site-foot-brand">
      <strong>Lovely Sunday</strong>
      <small>© {currentYear}</small>
    </div>

    <small class="site-foot-bio">
      A girl who left her corporate jobs to follow her passion as a blogger, creator &amp;
      stylist–Glitter obsessed and always in search of all things Lovely.
    </small>

    <nav class="site-foot-nav" aria-label="Footer">
      {links.map((link) => (
        <a
          href={link.href}
          target={link.external ? "_blank" : undefined}
          rel={link.external ? "noopener noreferrer" : undefined}
        >
          {link.label}
        </a>
      ))}
    </nav>
  </div>
</footer>

