--- slug page ---
---
import { loadLegacyPages } from "../lib/legacy-pages";
import LegacyHtmlPage from "../components/LegacyHtmlPage.astro";

export function getStaticPaths() {
  const legacyPages = loadLegacyPages();
  const explicitRoutes = new Set(["/about-lovely-sunday", "/contact-lovely-sunday"]);

  // Deduplicate by pathname — double-slash URLs (e.g. /lookbook//looks/x)
  // normalize to the same pathname as their single-slash counterparts.
  // Keep the last occurrence (single-slash canonical version comes after
  // double-slash in manifest order).
  const byPathname = new Map();
  for (const page of legacyPages) {
    if (page.pathname === "/") continue;
    if (explicitRoutes.has(page.pathname)) continue;
    byPathname.set(page.pathname, page);
  }

  return [...byPathname.values()].map((page) => {
    const slug = page.pathname.replace(/^\//, "");
    return {
      params: { slug },
      props: {
        page,
      },
    };
  });
}

const { page } = Astro.props;
---

<LegacyHtmlPage page={page} />
--- PostLayout ---
---
import Layout from '../layouts/Layout.astro';
import ImageBlock from './ImageBlock.astro';
import InstagramFeed from './InstagramFeed.astro';

export interface Props {
  title?: string;
  description?: string;
  thumbnail?: string;
  articleClass?: string;
  includeExcerpt?: boolean;
  slug?: string;
  seo?: {
    pageType?: "article" | "website" | "collection" | "profile" | "contact" | "confirmation";
    publishedTime?: string;
    modifiedTime?: string;
  };
}

const {
  title,
  description,
  thumbnail,
  articleClass = 'post-content',
  includeExcerpt = false,
  slug,
  seo,
} = Astro.props;

const resolvedTitle = title || "";
---

<Layout
  title={resolvedTitle}
  description={description}
  seo={{
    pageType: seo?.pageType || "article",
    image: thumbnail,
    publishedTime: seo?.publishedTime,
    modifiedTime: seo?.modifiedTime,
  }}
>
  <article class={`${articleClass} ${thumbnail ? '' : 'no-image'}`.trim()}>
    {includeExcerpt && description && <p class="post-content-excerpt">{description}</p>}
    <ImageBlock src={thumbnail} alt={resolvedTitle} />

    <div class="post-content-body">
      <slot />
    </div>

    <slot name="after" />

    <InstagramFeed
      title={resolvedTitle}
      description={description}
      slug={slug}
      heading="Inspired by @_lovelysunday"
      limit={6}
    />
  </article>
</Layout>
--- content.css post-content-image ---



