import { getInstagramMedia, getRelevantInstagramMedia } from "../lib/instagram";

interface Props {
  title?: string;
  description?: string;
  slug?: string;
  heading?: string;
  limit?: number;
}

const {
  title,
  description,
  slug,
  heading = "From Instagram",
  limit = 6,
} = Astro.props;

