/* Stage v1 — Layout, grid & consistency
/* Active while <html data-design> contains "v1". Every rule is additive
/* over the baseline stylesheets so the stage can be switched at runtime.
/* ---------------------------------------------------------- */

/* Shell: one container, one gutter ------------------------- */

html[data-design~="v1"] .site-main {
  padding: var(--block-gap) var(--gutter) var(--section-gap);
}

html[data-design~="v1"] .site-wrapper {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--color-border) 35%, transparent) 1px, transparent 1px)
      50% 0 / min(100% - 2 * var(--gutter), var(--container)) 100% no-repeat,
    var(--color-bg);
}

html[data-design~="v1"] .site-head {
  z-index: var(--z-header);
}

html[data-design~="v1"] .site-head-container,
html[data-design~="v1"] .site-foot-inner {
  max-width: calc(var(--container) + 2 * var(--gutter));
  padding-inline: var(--gutter);
}

html[data-design~="v1"] .site-head-container {
  gap: var(--space-8);
}

html[data-design~="v1"] .site-foot {
  position: relative;
  overflow: hidden;
  margin-top: 0;
  padding: var(--space-7) 0 var(--space-8);
}

html[data-design~="v1"] .site-foot-logo {
  display: none;
}

html[data-design~="v1"] .site-foot-inner {
  gap: var(--space-4);
}

html[data-design~="v1"] .site-foot-nav {
  gap: var(--space-5);
}

/* Legacy pages (home, lookbook, diary, looks) --------------- */

html[data-design~="v1"] .legacy-page {
  width: min(100%, var(--container));
  gap: var(--section-gap);
  padding-bottom: 0;
}

html[data-design~="v1"] .legacy-page--home {
  gap: var(--section-gap);
}

html[data-design~="v1"] .legacy-page-hero {
  gap: var(--block-gap);
}

html[data-design~="v1"] .legacy-page-copy {
  gap: var(--space-4);
}

html[data-design~="v1"] .legacy-page--home .legacy-page-copy {
  gap: var(--space-5);
  padding-right: clamp(0rem, 4vw, 4.8rem);
}

html[data-design~="v1"] .legacy-page-body {
  gap: var(--space-4);
}

/* Gallery/list pages: the article itself becomes the wide container and every
   non-gallery row steps back to the standard container. This replaces the
   `100vw` breakout that could not be centered and overflowed the viewport. */
html[data-design~="v1"] .legacy-page--gallery,
html[data-design~="v1"] .legacy-page--list {
  width: min(100%, var(--container-wide));
}

html[data-design~="v1"] .legacy-page--gallery > :not(.legacy-page-gallery),
html[data-design~="v1"] .legacy-page--list > :not(.legacy-page-gallery) {
  width: min(100%, var(--container));
  justify-self: center;
}

html[data-design~="v1"] .legacy-page--gallery .legacy-page-gallery,
html[data-design~="v1"] .legacy-page--list .legacy-page-gallery {
  width: 100%;
  justify-self: stretch;
}

html[data-design~="v1"] .legacy-page-gallery,
html[data-design~="v1"] .legacy-page--home .legacy-page-gallery {
  gap: var(--grid-gap);
}

/* Radius lives on the media container, never on the image. */
html[data-design~="v1"] .legacy-page-frame,
html[data-design~="v1"] .legacy-page-hero-media {
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-bg-subtle);
}

html[data-design~="v1"] .legacy-page-frame img,
html[data-design~="v1"] .legacy-page-hero-media img,
html[data-design~="v1"] .legacy-page--gallery .legacy-page-frame img {
  border-radius: 0;
}

html[data-design~="v1"] .legacy-page--home .legacy-page-hero-media {
  border-radius: 14rem 14rem var(--radius-lg) var(--radius-lg);
}

html[data-design~="v1"] .legacy-page--home .legacy-page-hero-media img {
  border-radius: 0;
}

/* CTA pills: hero → CTA is a block gap, not a section gap. */
html[data-design~="v1"] .legacy-page--home .legacy-page-links {
  margin-top: calc(var(--block-gap) - var(--section-gap));
}

html[data-design~="v1"] .legacy-page-links ul {
  gap: var(--space-3);
}

html[data-design~="v1"] .legacy-page-links a {
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-pill);
}

html[data-design~="v1"] .legacy-page--home .legacy-page-links a {
  padding-inline: var(--space-5);
  white-space: nowrap;
}

/* Images: undo the global 10px radius (it also rounded the logo). ---- */

html[data-design~="v1"] img,
html[data-design~="v1"] .kg-image,
html[data-design~="v1"] img.gatsby-resp-image-image {
  border-radius: 0 !important;
}

/* Posts, contact, thanks ----------------------------------- */

html[data-design~="v1"] .post-content,
html[data-design~="v1"] .contact-form {
  width: min(100%, var(--container-prose));
  max-width: none;
  margin: 0 auto;
  padding: 0;
}

html[data-design~="v1"] .post-content-image {
  width: auto;
  min-width: 0;
  max-width: none;
  margin: 0 0 var(--space-6);
  transform: none;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-bg-subtle);
}

html[data-design~="v1"] .post-content-image img {
  width: 100%;
  display: block;
  border: 0;
}

html[data-design~="v1"] .post-link {
  margin-top: var(--space-8);
  padding-top: var(--space-5);
}

