/* Stage v3 — Motion & interaction
/* Active while <html data-design> contains "v3". Scroll reveal is driven
/* by src/scripts/reveal.ts and only engages once <html class="reveal-ready">
/* is set (JS present, IntersectionObserver present, reduced motion off).
/* ---------------------------------------------------------- */

/* Page transition: quiet crossfade + 12px, no load-time slide ---- */

html[data-design~="v3"] .transition-fade {
  animation: none;
  transform: none;
  transition: none;
  opacity: 1;
}

html[data-design~="v3"].is-changing .transition-fade {
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
  will-change: opacity, transform;
}

html[data-design~="v3"].is-animating .transition-fade {
  opacity: 0;
  transform: translateY(var(--reveal-distance));
}

/* Scroll reveal --------------------------------------------- */

html[data-design~="v3"].reveal-ready [data-reveal] {
  opacity: 0;
  transform: translateY(var(--reveal-distance));
  transition:
    opacity var(--reveal-duration) var(--ease-out) var(--reveal-delay, 0ms),
    transform var(--reveal-duration) var(--ease-out) var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}

html[data-design~="v3"].reveal-ready [data-reveal].is-visible {
  opacity: 1;
  transform: none;
  will-change: auto;
}

/* Hover language -------------------------------------------- */

/* Media zoom: gentle on decorative frames, standard on linked media. */
html[data-design~="v3"] .legacy-page-frame img,
html[data-design~="v3"] .legacy-page-hero-media img,
html[data-design~="v3"] .post-card-image,
html[data-design~="v3"] .post-content-image img {
  transition: transform var(--dur-slow) var(--ease-out);
}

html[data-design~="v3"] .legacy-page-frame:hover img {
  transform: scale(1.01);
}

html[data-design~="v3"] .post-card-link:hover .post-card-image,
html[data-design~="v3"] .post-card-link:focus-visible .post-card-image {
  transform: scale(var(--hover-scale));
}

/* Navigation: underline grows in from the left (shared with footer). */
html[data-design~="v3"] .site-head-nav a,
html[data-design~="v3"] .site-foot-nav a {
  position: relative;
  transition:
    opacity var(--dur-base) var(--ease-out),
    color var(--dur-base) var(--ease-out);
}

html[data-design~="v3"] .site-head-nav a::after,
html[data-design~="v3"] .site-foot-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0.13em;
  bottom: 0.55rem;
  height: 1px;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform var(--dur-base) var(--ease-out);
}

html[data-design~="v3"] .site-head-nav a:hover::after,
html[data-design~="v3"] .site-head-nav a[aria-current="page"]::after,
html[data-design~="v3"] .site-foot-nav a:hover::after,
html[data-design~="v3"] .site-foot-nav a:focus-visible::after {
  transform: scaleX(1);
  transform-origin: left;
}

/* Pills */
html[data-design~="v3"] .legacy-page-links a {
  transition:
    border-color var(--dur-base) var(--ease-out),
    color var(--dur-base) var(--ease-out),
    background-color var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
}

html[data-design~="v3"] .legacy-page-links a:hover,
html[data-design~="v3"] .legacy-page-links a:focus-visible {
  transform: translateY(-1px);
  background-color: color-mix(in srgb, var(--color-accent) 8%, transparent);
}

/* Inline links: colour + drawn underline instead of the global text-decoration */
html[data-design~="v3"] a {
  transition: color var(--dur-base) var(--ease-out);
}

html[data-design~="v3"] a:hover {
  transition: color var(--dur-fast) var(--ease-out);
}

html[data-design~="v3"] .post-content-body a,
html[data-design~="v3"] .legacy-page-body a,
html[data-design~="v3"] .legacy-page-copy a,
html[data-design~="v3"] .post-link a {
  text-decoration: none;
  background-image: linear-gradient(currentColor, currentColor);
  background-size: 0% 1px;
  background-repeat: no-repeat;
  background-position: 0 100%;
  transition:
    background-size var(--dur-base) var(--ease-out),
    color var(--dur-base) var(--ease-out);
}

html[data-design~="v3"] .post-content-body a:hover,
html[data-design~="v3"] .legacy-page-body a:hover,
html[data-design~="v3"] .legacy-page-copy a:hover,
html[data-design~="v3"] .post-link a:hover {
  text-decoration: none;
  background-size: 100% 1px;
}

/* Buttons & inputs */
html[data-design~="v3"] .button,
html[data-design~="v3"] button,
html[data-design~="v3"] input[type="submit"],
html[data-design~="v3"] input[type="reset"],
html[data-design~="v3"] input[type="button"] {
  transition:
    background-color var(--dur-fast) var(--ease-out),
    color var(--dur-fast) var(--ease-out),
    border-color var(--dur-fast) var(--ease-out),
    box-shadow var(--dur-fast) var(--ease-out);
}

html[data-design~="v3"] input[type="text"],
html[data-design~="v3"] input[type="email"],
html[data-design~="v3"] select,
html[data-design~="v3"] textarea {
  transition:
    border-color var(--dur-fast) var(--ease-out),
    box-shadow var(--dur-fast) var(--ease-out);
}

/* Footer wordmark: drawn on when the footer scrolls into view ---- */

html[data-design~="v3"] .site-foot {
  position: relative;
  overflow: hidden;
  min-height: clamp(24rem, 30vw, 36rem);
  display: grid;
  align-content: start;
}

html[data-design~="v3"] .site-foot .site-foot-logo {
  display: grid;
  align-items: end;
  justify-items: center;
  opacity: 0.14;
  padding-bottom: var(--space-4);
  pointer-events: none;
}

html[data-design~="v3"] .site-foot .site-foot-logo svg {
  width: min(88vw, 720px);
}

html[data-design~="v3"] .site-foot-logo svg .st0 {
  animation: footer-logo-write 3.2s var(--ease-out) forwards;
  animation-play-state: paused;
}

html[data-design~="v3"] .site-foot.is-visible .site-foot-logo svg .st0 {
  animation-play-state: running;
}

/* Accessibility --------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  html[data-design~="v3"] .transition-fade,
  html[data-design~="v3"] [data-reveal],
  html[data-design~="v3"] .legacy-page-links a,
  html[data-design~="v3"] .site-head-nav a::after,
  html[data-design~="v3"] .site-foot-nav a::after,
  html[data-design~="v3"] img {
    transition: none !important;
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }

  html[data-design~="v3"] .site-head-nav a[aria-current="page"]::after {
    transform: scaleX(1) !important;
  }

  html[data-design~="v3"] .site-foot-logo svg .st0 {
    animation: none !important;
    stroke-dashoffset: 0;
  }
}

@media print {
  [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
  }
}
