/**
 * Client runtime for the design stages.
 *
 * - Initialises Swup (page transitions) so hooks can be shared.
 * - Scroll reveal for `[data-reveal]` elements when stage v3 is active.
 * - Keeps the header's `aria-current` correct after client-side navigation.
 * - Listens for `design:change` from the stage toggle and re-binds in place.
 */
import Swup from "swup";
import HeadPlugin from "@swup/head-plugin";

const root = document.documentElement;
const REVEAL_SELECTOR = "[data-reveal]";
const WATCH_SELECTOR = "[data-reveal], [data-reveal-watch], .post-card";

let observer: IntersectionObserver | null = null;

const reducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const stageOn = (stage: string) => (root.dataset.design ?? "").split(/\s+/).includes(stage);
const motionEnabled = () => stageOn("v3") && !reducedMotion() && "IntersectionObserver" in window;

function showEverything() {
  document.querySelectorAll(WATCH_SELECTOR).forEach((el) => el.classList.add("is-visible"));
}

function bindReveal() {
  observer?.disconnect();
  observer = null;

  if (!motionEnabled()) {
    root.classList.remove("reveal-ready");
    // Baseline `.post-card` reveal (animations.css) still needs `is-visible`,
    // and nothing may stay hidden when motion is off.
    showEverything();
    return;
  }

  root.classList.add("reveal-ready");

  observer = new IntersectionObserver(
    (entries) => {
      let index = 0;
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        const el = entry.target as HTMLElement;
        if (el.matches(REVEAL_SELECTOR)) {
          // Batch-based stagger: items entering together cascade, capped at 300ms.
          el.style.setProperty("--reveal-delay", `${Math.min(index, 6) * 50}ms`);
          index += 1;
        }
        el.classList.add("is-visible");
        observer?.unobserve(el);
      }
    },
    { threshold: 0.12, rootMargin: "0px 0px -8% 0px" },
  );

  document
    .querySelectorAll(`${WATCH_SELECTOR}`)
    .forEach((el) => {
      if (!el.classList.contains("is-visible")) observer?.observe(el);
    });
}

/** When motion is switched on mid-page, re-arm anything still below the fold. */
function rearmBelowFold() {
  const fold = window.innerHeight;
  document.querySelectorAll<HTMLElement>(REVEAL_SELECTOR).forEach((el) => {
    if (el.getBoundingClientRect().top > fold) {
      el.classList.remove("is-visible");
      el.style.removeProperty("--reveal-delay");
    }
  });
}

function updateAriaCurrent() {
  const path = location.pathname.replace(/\/+$/, "") || "/";
  document.querySelectorAll<HTMLAnchorElement>(".site-head-nav a[data-section]").forEach((link) => {
    const sections = (link.dataset.section ?? "").split(/\s+/).filter(Boolean);
    const current = sections.some((section) => path === section || path.startsWith(`${section}/`));
    if (current) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
}

const swup = new Swup({
  containers: ["#swup"],
  cache: true,
  animationSelector: "[class*='transition-']",
  plugins: [new HeadPlugin()],
});

swup.hooks.on("page:view", () => {
  bindReveal();
  updateAriaCurrent();
});

window.addEventListener("design:change", () => {
  if (motionEnabled()) rearmBelowFold();
  bindReveal();
});

bindReveal();
updateAriaCurrent();
EOF
