    width: min(100%, var(--container));
    margin-inline: auto;
}

.container-wide {
    width: min(100%, var(--container-wide));
    margin-inline: auto;
}

.container-prose {
    width: min(100%, var(--container-prose));
    margin-inline: auto;
}

/* Post feed (List template / Storybook)
/* ---------------------------------------------------------- */

.post-feed {
    display: grid;
    grid-template-columns: 1.15fr 0.85fr;
    gap: var(--space-5);
    max-width: var(--container);
    margin: 0 auto;
}

/* Every 5th card (starting from 3rd) spans full width for variety */
.post-feed .post-card:nth-child(5n+3) {
    grid-column: 1 / -1;
}

.page-head {
    text-align: center;
    max-width: var(--container-prose);
    margin: 0 auto var(--block-gap);
    padding: 0;
