/* Animations
/* ---------------------------------------------------------- */

/* Swup page transition: a quiet crossfade with a 12px rise. Nothing moves on
   first load. */
.transition-fade {
  opacity: 1;
  transform: none;
}

html.is-changing .transition-fade {
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
  will-change: opacity, transform;
}

html.is-animating .transition-fade {
  opacity: 0;
  transform: translateY(var(--reveal-distance));
}

/* Scroll reveal. Elements carry `data-reveal`; src/scripts/reveal.ts adds
   `is-visible` as they enter the viewport. The `reveal-ready` class is set on
   <html> only when IntersectionObserver exists and reduced motion is off, so
   nothing is ever hidden without JS. */
html.reveal-ready [data-reveal] {
  opacity: 0;
  transform: translateY(var(--reveal-distance));
  transition:
    opacity var(--reveal-duration) var(--ease-out) var(--reveal-delay, 0ms),
    transform var(--reveal-duration) var(--ease-out) var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}

html.reveal-ready [data-reveal].is-visible {
  opacity: 1;
  transform: none;
  will-change: auto;
}

@media (prefers-reduced-motion: reduce) {
  .transition-fade,
  [data-reveal] {
    transition: none !important;
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}

@media print {
  [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
  }
}
EOF
