/* Site Wrapper
/* ---------------------------------------------------------- */

.site-wrapper {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--color-border) 35%, transparent) 1px, transparent 1px)
      50% 0 / min(100% - 2 * var(--gutter), var(--container)) 100% no-repeat,
    var(--color-bg);
  min-height: 100vh;
  color: var(--color-base);
  font-family: var(--font-serif);
  position: relative;
