.site-head-nav a {
  opacity: 0.6;
}

.site-foot-nav a {
  opacity: 0.68;
}

.site-head-nav a::after,
.site-foot-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0.13em;
  bottom: 0.55rem;
  height: 1px;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform var(--dur-base) var(--ease-out);
}

.site-head-nav a:hover,
.site-head-nav a[aria-current='page'],
.site-foot-nav a:hover {
  opacity: 1;
  color: var(--color-accent);
  text-decoration: none;
}

.site-head-nav a:hover::after,
.site-head-nav a[aria-current='page']::after,
.site-foot-nav a:hover::after,
.site-foot-nav a:focus-visible::after {
  transform: scaleX(1);
  transform-origin: left;
}

.site-head a:focus-visible,
.site-foot a:focus-visible {
  outline: 2px solid var(--color-accent);
