/* Site Wrapper
/* ---------------------------------------------------------- */

.site-wrapper {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--color-border) 35%, transparent) 1px, transparent 1px)
      50% 0 / min(100% - 2 * var(--gutter), var(--container)) 100% no-repeat,
    var(--color-bg);
  min-height: 100vh;
  color: var(--color-base);
  font-family: var(--font-serif);
  position: relative;
}

.site-content-shell {
  position: relative;
  z-index: 2;
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
}

[data-theme='dark'] .site-wrapper {
  background: radial-gradient(circle at top, rgba(201, 166, 160, 0.05), transparent 50%),
    var(--color-bg);
}

/* Header
/* ---------------------------------------------------------- */

.site-head {
  position: sticky;
  top: 0;
  width: 100%;
  background: color-mix(in srgb, var(--color-bg) 95%, transparent);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--color-border);
  z-index: var(--z-header);
}

.site-head-container {
  width: 100%;
  max-width: calc(var(--container) + 2 * var(--gutter));
  margin: 0 auto;
  padding: 0 var(--gutter);
  height: var(--header-height);
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: var(--space-8);
}

.site-head-logo img {
  display: block;
  width: clamp(10rem, 13vw, 13.5rem);
  max-height: calc(var(--header-height) - 1rem);
  border-radius: 0;
}

.site-head-nav {
  display: flex;
  justify-content: flex-end;
  gap: clamp(1.2rem, 3vw, 2.6rem);
  align-items: center;
}

/* Navigation links (header + footer share one spec) */

.site-head-nav a,
.site-foot-nav a {
  position: relative;
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  font-family: var(--font-sans-serif);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  font-weight: 400;
  color: var(--color-base);
  text-decoration: none;
  transition:
    opacity var(--dur-base) var(--ease-out),
    color var(--dur-base) var(--ease-out);
}

.site-head-nav a {
  opacity: 0.6;
}

.site-foot-nav a {
  opacity: 0.68;
}

.site-head-nav a::after,
.site-foot-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0.13em;
  bottom: 0.55rem;
  height: 1px;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform var(--dur-base) var(--ease-out);
}

.site-head-nav a:hover,
.site-head-nav a[aria-current='page'],
.site-foot-nav a:hover {
  opacity: 1;
  color: var(--color-accent);
  text-decoration: none;
}

.site-head-nav a:hover::after,
.site-head-nav a[aria-current='page']::after,
.site-foot-nav a:hover::after,
.site-foot-nav a:focus-visible::after {
  transform: scaleX(1);
  transform-origin: left;
}

.site-head a:focus-visible,
.site-foot a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

