  z-index: 2;
}

.site-foot-brand strong {
  font-family: var(--font-display);
  font-weight: 300;
  letter-spacing: 0.04em;
  font-size: var(--text-lg);
}

.site-foot-brand small {
  font-size: var(--text-sm);
}

.site-foot-bio {
  flex: 1 1 auto;
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 4rem);
