  text-align: center;
  max-width: 58ch;
  white-space: normal;
  color: var(--color-base);
  opacity: 0.6;
}

.site-foot-nav {
  display: flex;
  gap: var(--space-5);
  flex-wrap: wrap;
}

@keyframes footer-logo-write {
  to {
    stroke-dashoffset: 0;
  }
