@media (max-width: 700px) {
  .site-head-container {
    height: auto;
    grid-template-columns: 1fr;
    gap: var(--space-2);
    padding-block: var(--space-3) var(--space-2);
  }

  .site-head-logo {
    justify-self: center;
  }

  .site-head-logo img {
    width: 11rem;
  }

  .site-head-nav {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 0;
  }

  .site-head-nav a {
    justify-content: center;
  }

  .site-foot {
    min-height: 0;
    padding-bottom: var(--space-7);
  }

  .site-foot-inner {
    flex-direction: column;
    align-items: flex-start;
  }

  .site-foot-bio {
    order: 3;
    width: 100%;
    padding-inline: 0;
    text-align: left;
  }

  .site-foot-logo {
    opacity: 0.1;
  }
