/* Rendered by src/components/LegacyHtmlPage.astro from captured data.
/* ---------------------------------------------------------- */

.legacy-page {
  width: min(100%, var(--container));
  margin: 0 auto;
  display: grid;
  gap: var(--section-gap);
}

