/* ---------------------------------------------------------- */

.legacy-page-hero {
  display: grid;
  gap: var(--block-gap);
  align-items: start;
}

.legacy-page-hero.has-media {
  grid-template-columns: minmax(0, 1fr) minmax(280px, 34rem);
}

.legacy-page-copy {
  display: grid;
  gap: var(--space-4);
}

.legacy-page h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: var(--text-3xl);
  line-height: var(--leading-tight);
  font-weight: 400;
  letter-spacing: 0;
}

.legacy-page p {
  margin: 0;
  font-size: var(--text-md);
  line-height: var(--leading-body);
  max-width: 62ch;
}

.legacy-page-copy > p.lead {
  font-size: var(--text-lg);
  line-height: 1.6;
  max-width: 48ch;
  color: color-mix(in srgb, var(--color-base) 78%, transparent);
}

.legacy-page-eyebrow {
  max-width: none;
}

/* Media: radius lives on the container so hover zoom keeps its corners */

.legacy-page-hero-media,
.legacy-page-frame {
  margin: 0;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-bg-subtle);
}

.legacy-page-hero-media img,
.legacy-page-frame img {
  width: 100%;
  height: auto;
  display: block;
  transition: transform var(--dur-slow) var(--ease-out);
}

.legacy-page-frame:hover img {
  transform: scale(1.01);
}

/* Home
/* ---------------------------------------------------------- */

.legacy-page--home .legacy-page-hero {
  min-height: min(680px, calc(100vh - var(--header-height) - 7rem));
  grid-template-columns: minmax(0, 0.82fr) minmax(340px, 1.18fr);
  align-items: center;
}

.legacy-page--home .legacy-page-copy {
  gap: var(--space-5);
  padding-right: clamp(0rem, 4vw, 4.8rem);
}

.legacy-page--home h1 {
  max-width: 10ch;
  font-size: var(--text-display);
  line-height: 0.9;
  letter-spacing: var(--tracking-display);
  font-weight: 300;
}

.legacy-page--home .legacy-page-copy > p:not(.legacy-page-eyebrow) {
  max-width: 42ch;
  color: color-mix(in srgb, var(--color-base) 72%, transparent);
  font-size: var(--text-lg);
  line-height: 1.6;
}

.legacy-page--home .legacy-page-hero-media {
  align-self: stretch;
  min-height: 34rem;
  border-radius: 14rem 14rem var(--radius-lg) var(--radius-lg);
}

.legacy-page--home .legacy-page-hero-media img {
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
  filter: saturate(0.88) contrast(1.02);
}

/* Hero → CTA is a block gap, not a section gap */
.legacy-page--home .legacy-page-links {
  margin-top: calc(var(--block-gap) - var(--section-gap));
}

.legacy-page--home .legacy-page-links ul {
  display: flex;
  flex-wrap: wrap;
}

.legacy-page--home .legacy-page-links a {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  padding-inline: var(--space-5);
  white-space: nowrap;
}

.legacy-page--home .legacy-page-gallery {
  grid-template-columns: repeat(12, minmax(0, 1fr));
}

.legacy-page--home .legacy-page-frame {
  grid-column: span 4;
}

.legacy-page--home .legacy-page-frame:nth-child(5n + 1),
.legacy-page--home .legacy-page-frame:nth-child(5n + 4) {
  grid-column: span 8;
}

.legacy-page--home .legacy-page-frame img {
  height: clamp(22rem, 38vw, 34rem);
  object-fit: cover;
}

/* Links (CTA pills)
/* ---------------------------------------------------------- */

.legacy-page-links ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: var(--space-3);
}

.legacy-page-links a {
  display: block;
  padding: var(--space-3) var(--space-5);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  text-decoration: none;
  color: var(--color-base);
  transition:
    border-color var(--dur-base) var(--ease-out),
    color var(--dur-base) var(--ease-out),
    background-color var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
}

.legacy-page-links a:hover,
.legacy-page-links a:focus-visible {
  color: var(--color-accent);
  border-color: var(--color-accent);
  background-color: color-mix(in srgb, var(--color-accent) 8%, transparent);
  transform: translateY(-1px);
}

/* Gallery
/* ---------------------------------------------------------- */

.legacy-page-gallery {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--grid-gap);
}

/* Gallery and list pages: the article is the wide container and every
   non-gallery row steps back to the standard one. */
.legacy-page--gallery,
.legacy-page--list {
  width: min(100%, var(--container-wide));
}

.legacy-page--gallery > :not(.legacy-page-gallery),
.legacy-page--list > :not(.legacy-page-gallery) {
  width: min(100%, var(--container));
  justify-self: center;
}

.legacy-page--gallery .legacy-page-frame {
  min-width: 0;
}

.legacy-page--gallery .legacy-page-frame.is-full-span {
  grid-column: 1 / -1;
}

.legacy-page--gallery .legacy-page-frame.is-half-span {
  grid-column: span 1;
  aspect-ratio: 2 / 3;
}

.legacy-page--gallery .legacy-page-frame.is-half-span img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.legacy-page-body {
  display: grid;
  gap: var(--space-4);
}

.legacy-page-body a,
.legacy-page-copy a {
  text-decoration: none;
  background-image: linear-gradient(currentColor, currentColor);
  background-size: 0% 1px;
  background-repeat: no-repeat;
  background-position: 0 100%;
  transition:
    background-size var(--dur-base) var(--ease-out),
    color var(--dur-base) var(--ease-out);
}

.legacy-page-body a:hover,
.legacy-page-copy a:hover {
  text-decoration: none;
  background-size: 100% 1px;
}

/* Responsive
/* ---------------------------------------------------------- */

@media (max-width: 900px) {
  .legacy-page-hero.has-media {
    grid-template-columns: 1fr;
  }

  .legacy-page--home .legacy-page-hero {
    min-height: 0;
    grid-template-columns: 1fr;
  }

  .legacy-page--home .legacy-page-copy {
    padding-right: 0;
  }

  .legacy-page--home .legacy-page-hero-media {
    min-height: 28rem;
  }

  .legacy-page--home .legacy-page-links {
    margin-top: calc(var(--space-5) - var(--section-gap));
  }
}

@media (max-width: 640px) {
  .legacy-page--home h1 {
    font-size: clamp(4.2rem, 15vw, 5.6rem);
  }

  .legacy-page--home .legacy-page-links ul {
    display: grid;
    grid-template-columns: 1fr;
  }

  .legacy-page--home .legacy-page-links a {
    justify-content: center;
  }

  .legacy-page--home .legacy-page-frame,
  .legacy-page--home .legacy-page-frame:nth-child(5n + 1),
  .legacy-page--home .legacy-page-frame:nth-child(5n + 4) {
    grid-column: span 6;
  }

  .legacy-page--home .legacy-page-frame:nth-child(3n + 1) {
    grid-column: 1 / -1;
  }

  .legacy-page--home .legacy-page-frame img {
    height: 24rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .legacy-page-links a,
  .legacy-page-frame img,
  .legacy-page-hero-media img {
    transition: none;
    transform: none;
  }
}
EOF
